let lang='ar';let reviewIndex=0;try{lang=localStorage.getItem('smartapply-language')==='en'?'en':'ar'}catch{}
const pick=(ar,en)=>lang==='ar'?ar:en;
const wa=(msg)=>'https://wa.me/250795331304?text='+encodeURIComponent(msg||pick('مرحباً SmartApply RW، أود معرفة المزيد عن الدراسة في رواندا والخدمات والأسعار.','Hello SmartApply RW, I would like to learn about studying in Rwanda, your services and pricing.'));
function bindWa(){document.querySelectorAll('a.wa').forEach(a=>{a.href=wa(a.dataset[lang==='ar'?'messageAr':'messageEn']||a.dataset.message);a.target='_blank';a.rel='noopener'})}
function reviews(){document.querySelector('#review-grid').innerHTML=Array.from({length:3},(_,i)=>{const r=data.reviews[(reviewIndex+i)%data.reviews.length];return `<article class="review-card"><div class="quote">“</div><p>${pick(r[0],r[1])}</p><div class="review-author"><div class="avatar">✦</div><div><strong>${pick(r[2],r[3])}</strong><small>${pick('نموذج توضيحي — ليس رأياً حقيقياً','Illustrative sample — not a real review')}</small></div></div></article>`}).join('');document.querySelector('#review-pagination').textContent=`${reviewIndex+1} / ${data.reviews.length}`}
const contactForm=document.querySelector('#contact-form');
const contactErrors={
  name:['يرجى إدخال اسمك، وليس مسافات فقط.','Please enter your name, not just spaces.'],
  message:['يرجى كتابة رسالتك، وليس مسافات فقط.','Please enter a message, not just spaces.']
};
function validateContactField(field){
  field.setCustomValidity(field.value.trim()?'':pick(...contactErrors[field.name]));
}
function refreshContactValidation(){
  Object.keys(contactErrors).forEach(name=>validateContactField(contactForm.elements.namedItem(name)));
}
Object.keys(contactErrors).forEach(name=>{
  const field=contactForm.elements.namedItem(name);
  field.addEventListener('input',()=>validateContactField(field));
  field.addEventListener('invalid',()=>validateContactField(field));
});
function renderFaqs(){
  const list=document.querySelector('#faq-list');
  const openQuestions=new Set(Array.from(list.querySelectorAll('details'),(item,i)=>item.open?i:-1));
  list.innerHTML=data.faq.map((f,i)=>`<details${openQuestions.has(i)?' open':''}><summary>${pick(f[0],f[1])}</summary><p>${pick(f[2],f[3])}</p></details>`).join('');
}
function renderLanguageAttributes(){
  document.querySelectorAll('[data-label-ar]').forEach(el=>{
    el.setAttribute('aria-label',pick(el.dataset.labelAr,el.dataset.labelEn));
  });
  document.querySelectorAll('[data-content-ar]').forEach(el=>{
    el.setAttribute('content',pick(el.dataset.contentAr,el.dataset.contentEn));
  });
}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=pick('SmartApply RW | مستقبلك يبدأ من رواندا','SmartApply RW | Your future starts in Rwanda');document.querySelectorAll('[data-ar]').forEach(el=>el.innerHTML=el.dataset[lang]);document.querySelector('#language').textContent=pick('EN ◉','العربية ◉');document.querySelector('#service-grid').innerHTML=data.services.map(s=>`<article class="service-card"><div class="service-icon">${s[0]}</div><h3>${pick(s[1],s[2])}</h3><p>${pick(s[3],s[4])}</p><a class="text-link wa" data-message="${pick('مرحباً، أريد تفاصيل خدمة: '+s[1],'Hello, I would like details about: '+s[2])}">${pick('اسأل عن الخدمة ↖','Ask about this service ↗')}</a></article>`).join('');document.querySelector('#university-grid').innerHTML=data.unis.map(u=>`<article class="uni-card"><div class="uni-photo"><img loading="lazy" src="assets/${u[1]}" alt="${u[3]}"><span class="uni-tag">${u[0]}</span></div><div class="uni-copy"><h3>${pick(u[2],u[3])}</h3><p>${pick(u[4],u[5])}</p><div class="uni-links"><a class="text-link wa" data-message="${pick('أرغب في التقديم إلى ','I would like to apply to ')+u[0]}">${pick('اسأل عن التقديم ↖','Ask about applying ↗')}</a><a href="${u[6]}" target="_blank" rel="noopener">${pick('الموقع الرسمي ↗','Official website ↗')}</a></div></div></article>`).join('');document.querySelector('#steps').innerHTML=data.steps.map((s,i)=>`<div class="step"><b>0${i+1}</b><h3>${pick(s[0],s[1])}</h3><p>${pick(s[2],s[3])}</p></div>`).join('');renderFaqs();reviews();bindWa();refreshContactValidation();renderLanguageAttributes()}
document.querySelector('#language').addEventListener('click',()=>{lang=lang==='ar'?'en':'ar';try{localStorage.setItem('smartapply-language',lang)}catch{}render()});document.querySelector('#menu').addEventListener('click',e=>{const open=document.querySelector('#nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});document.querySelectorAll('#nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false')}));document.querySelector('#prev-review').onclick=()=>{reviewIndex=(reviewIndex-1+data.reviews.length)%data.reviews.length;reviews()};document.querySelector('#next-review').onclick=()=>{reviewIndex=(reviewIndex+1)%data.reviews.length;reviews()};contactForm.addEventListener('submit',e=>{
  e.preventDefault();
  refreshContactValidation();
  if(!contactForm.reportValidity())return;
  const f=new FormData(contactForm);
  const name=f.get('name').trim();
  const nationality=f.get('nationality').trim();
  const subject=f.get('subject').trim();
  const message=f.get('message').trim();
  const msg=pick('مرحباً SmartApply RW،\n','Hello SmartApply RW,\n')+
    pick('الاسم: ','Name: ')+name+'\n'+
    pick('الجنسية: ','Nationality: ')+nationality+'\n'+
    pick('التخصص: ','Subject: ')+subject+'\n'+message;
  window.open(wa(msg),'_blank','noopener');
});document.querySelector('#sources').onclick=()=>document.querySelector('#credits').showModal();document.querySelector('#close-credits').onclick=()=>document.querySelector('#credits').close();render();
